import {createPlantAudio} from './plant-audio.js?v=station-speech-20261106';
import {createFieldSpeaker} from './field-speech.js?v=voice-diagnostic-20261106';
import {addCampusBrand} from './campus-map.js?v=school-map-20261109';
import {stations,directions,validStationLocation,latestViews,locatedStations,stationDescription,stationReadingContext} from './space-domain.js?v=school-map-20261109';
import {nearbyTrees,chooseNearbyTarget} from './field-domain.js?v=entry-restore-20261106';
export function mountSpaceCapture({getUser,isAdmin,compress,store,renderDrafts,stopOtherSpeech=()=>{}}){
 const section=document.querySelector('#space-capture');
 section.innerHTML=`<h2>校園空間定位拍照・簡易 VR</h2><p>同一站拍四張水平照片：前方、右方、後方、左方。以本站第一張的朝向為前方，補拍沿用同一基準。不拍天空或腳下。手機橫放，鏡頭約眼睛高度，轉身拍攝並保留部分重疊；照片用於左右切換導覽。</p><p><a href="./tour.html?mode=simple">查看四向實景導覽 →</a> · <a href="./capture.html">查看完整補拍地圖 →</a></p><button id="space-locate">開始空間定位</button> <button id="space-stop" disabled>停止定位</button><label><input id="space-follow" type="checkbox" checked> 隨手機位置顯示最近的已定位站點</label><p id="space-gps" role="status">第一次拍攝請先選站。俯視圖標點是建議位置，尚未取得 GPS 的站點不參與距離排序。</p><div class="space-map"><img src="./assets/campus-overview-reviewed-20261109.png" alt="校園補拍站點俯視圖，北朝左下方"><div id="space-pins"></div></div><label>目前拍攝站點<select id="space-station"></select></label><p id="space-target"></p><label><input id="space-voice" type="checkbox" checked> 自動朗讀站點說明（切站或確認本站時）</label><button id="space-read" type="button">朗讀目前站點</button> <button id="space-speech-stop" type="button">停止站點朗讀</button><audio id="space-audio" controls preload="none" aria-label="站點說明音訊播放器" style="display:block;width:100%;margin-top:12px"></audio><p id="space-speech-status" role="status">按「朗讀目前站點」會先重新定位；定位精度需在 ±25 公尺內，並距已定位站點 30 公尺內才朗讀。</p><div id="space-nearby"></div><label><input id="space-confirm" type="checkbox"> 我已在此站的安全位置，固定本站拍四個方向</label><p class="hint">確認時會固定站點與可靠 GPS；上傳照片會一併公開該拍攝站點座標。只在本頁定位而未上傳時不傳送位置。定位誤差大或室內無 GPS 時可依圖手動拍照，不會附上不可靠座標。</p><label>本張方向<select id="space-kind"></select></label><p id="space-instructions"></p><label class="camera-label">開啟相機拍這個方向<input id="space-camera" type="file" accept="image/*" capture="environment" disabled></label><label>或選擇相簿照片<input id="space-album" type="file" accept="image/*" disabled></label><p id="space-status" role="status"></p><div id="space-progress"></div><button id="space-refresh">重新確認發布進度</button> <button id="space-next">下一站</button>`;
 const $=s=>section.querySelector(s);let watch,position,fixedLocation,followed=false,records=[],local=[],busy=false,uid='',readRequest=0;
 addCampusBrand($('.space-map'));
 const versions=document.createElement('details');versions.className='map-version-reference';
 versions.innerHTML='<summary>兩版俯視圖參考</summary><p>拍照使用上方校方校對版入口視角與既有站號。下方可比較兩張圖，不變更拍照目標、GPS 或既有照片。</p><label>參考底圖<select class="reference-version"><option value="original">校方校對版：大門進入視角・北朝左下</option><option value="north">新版：正北朝上立體圖</option></select></label><div class="reference-map"><img alt="校方校對版大門進入視角校園圖" src="./assets/campus-overview-reviewed-20261109.png"></div>';
 $('.space-map').after(versions);const reference=versions.querySelector('.reference-map');addCampusBrand(reference);
 versions.querySelector('select').onchange=e=>{const north=e.target.value==='north';reference.querySelector('img').src=north?'./assets/campus-overview-3d-north-v4.png':'./assets/campus-overview-reviewed-20261109.png';reference.querySelector('img').alt=north?'新版正北朝上立體校園示意圖':'校方校對版大門進入視角校園示意圖';reference.querySelector('.map-north').hidden=north;};


 const speechStatus=text=>$('#space-speech-status').textContent=text;
 const stationSpeaker=createFieldSpeaker({synth:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,enabled:()=>$('#space-voice').checked,status:speechStatus,audioSession:navigator.audioSession,getVoice:()=>document.querySelector('#tts-voice')?.value||'recorded'});
 const stationAudio=createPlantAudio({audio:$('#space-audio'),status:speechStatus,stopSpeech:()=>stationSpeaker.stop()});
 const stopStationSpeech=()=>{readRequest++;stationAudio.stop();stationSpeaker.stop();};
 function readStation(manual=true){if(!manual&&!$('#space-voice').checked)return;const station=stations.find(s=>s.id===$('#space-station').value);if(!station)return;document.dispatchEvent(new Event('teacher-read-target'));stopOtherSpeech();const mode=document.querySelector('#tts-voice')?.value||'recorded';if(mode==='recorded')stationAudio.play(station.id,{manual});else{stationAudio.stop();stationSpeaker.speak(stationDescription(station),{manual});}}
 $('#space-read').onclick=()=>{
  stopStationSpeech();stop();stopOtherSpeech();
  if(!isAdmin()||busy){speechStatus('請先登入並等待照片保存完成，再定位朗讀。');return;}
  if(!navigator.geolocation){speechStatus('此瀏覽器不支援定位，無法確認目前站點。');return;}
  const request=readRequest;speechStatus('正在重新定位，確認附近站點後朗讀…');
  navigator.geolocation.getCurrentPosition(p=>{
   if(request!==readRequest||!isAdmin()||busy||document.hidden)return;
   const fix={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,time:p.timestamp};
   const result=stationReadingContext([...local,...records],fix);$('#space-gps').textContent=result.message;
   if(!result.station){speechStatus(result.message);return;}
   position=fix;select(result.station.id,true,false);readStation(true);
  },error=>{
   if(request!==readRequest||!isAdmin()||document.hidden)return;
   speechStatus(error.code===1?'定位權限未開啟，請允許位置存取後再朗讀。':'定位暫時無法取得，請移到空曠處重試；尚未朗讀站點。');
  },{enableHighAccuracy:true,maximumAge:0,timeout:20000});
 };$('#space-speech-stop').onclick=stopStationSpeech;
 $('#space-voice').onchange=()=>{if($('#space-voice').checked)readStation(true);else{stopStationSpeech();speechStatus('自動站點朗讀已關閉，仍可手動播放。');}};
 document.addEventListener('teacher-read-target',stopStationSpeech);
 document.querySelector('#tts-voice')?.addEventListener('change',stopStationSpeech);
 window.addEventListener('pagehide',stopStationSpeech);
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopStationSpeech();});
 const requested=new URLSearchParams(location.search).get('station');
 for(const s of stations){const o=document.createElement('option');o.value=s.id;o.textContent=`${s.id} ${s.name}`;$('#space-station').append(o);const b=document.createElement('button');b.type='button';b.textContent=s.id;b.style.left=`${s.x}%`;b.style.top=`${s.y}%`;b.onclick=()=>select(s.id,true);$('#space-pins').append(b);}
 if(stations.some(s=>s.id===requested))$('#space-station').value=requested;
 for(const [value,label] of directions){const o=document.createElement('option');o.value=value;o.textContent=label;$('#space-kind').append(o);}
 function stop(){readRequest++;if(watch!==undefined)navigator.geolocation?.clearWatch(watch);watch=undefined;$('#space-locate').disabled=false;$('#space-stop').disabled=true;}
 function lock(){const confirmed=$('#space-confirm').checked;if(confirmed){$('#space-follow').checked=false;if(fixedLocation===undefined)fixedLocation=validStationLocation(position)&&Date.now()-position.time<=20000?{latitude:position.latitude,longitude:position.longitude,accuracy:position.accuracy}:null;}else fixedLocation=undefined;$('#space-camera').disabled=$('#space-album').disabled=!confirmed||busy;}
 function select(id,manual=false,announce=true){if(busy)return;readRequest++;$('#space-station').value=id;$('#space-confirm').checked=false;fixedLocation=undefined;if(manual){$('#space-follow').checked=false;followed=false;}lock();render();if(announce&&$('#space-voice').checked)readStation(manual);}
 function render(){const id=$('#space-station').value,s=stations.find(s=>s.id===id);$('#space-target').textContent=`${s.id}｜${s.name}（建議區域・待現勘）：${s.note}`;const published=latestViews(records,id),saved=latestViews(local,id);$('#space-progress').replaceChildren();for(const [kind,label] of directions){const p=document.createElement('p');p.textContent=`${label}：${published[kind]?'已在網站發布':saved[kind]?saved[kind].state==='published'?'GitHub 已接收，等待網站發布':'已存本機，待上傳':'尚未拍攝'}`;$('#space-progress').append(p);}const missing=directions.find(([kind])=>!published[kind]&&!saved[kind]);if(missing)$('#space-kind').value=missing[0];instructions();for(const b of $('#space-pins').children)b.setAttribute('aria-pressed',String(b.textContent===id));}
 function instructions(){$('#space-instructions').textContent=`本張拍攝${directions.find(([kind])=>kind===$('#space-kind').value)[1]}。以本站第一張照片的朝向為前方，補拍沿用原本的前方；站在同一安全位置，手機橫放、鏡頭約眼睛高度並保持水平，依前方→右方→後方→左方各拍一張，不拍天空或腳下；儲存前核對本站站號與本張方向，勿站車道、攀牆或進入危險區域。四張都存好後，在下方逐張按「上傳公開」。`;}
 async function refresh(){try{const response=await fetch('./public-photos.json',{cache:'no-store'});if(!response.ok)throw Error();records=await response.json();local=isAdmin()?(await store('getAll')).filter(d=>d.owner===getUser()?.uid):[];render();}catch{$('#space-status').textContent='進度暫時無法載入，可重試；照片仍保存在本機。';}}
 function update(){if(!position)return;const nearby=nearbyTrees(locatedStations([...local,...records]),position);const nearest=chooseNearbyTarget(nearby,followed?$('#space-station').value:null,position.accuracy);if($('#space-follow').checked&&nearest.tree){followed=true;if(nearest.tree.id!==$('#space-station').value)select(nearest.tree.id);}
  $('#space-gps').textContent=`定位精度約 ±${Math.round(position.accuracy)} 公尺。${position.accuracy>25?'誤差較大，暫不自動換站。':!nearby.length?'尚無已定位站點，請在圖上選站並確認位置，拍攝後上傳以建立站點 GPS。':$('#space-follow').checked?`附近已定位站點：${nearby[0].id} ${nearby[0].name}，約 ${Math.round(nearby[0].distance)} 公尺。`:'目前站點已固定，可安心拍完四個方向。'}`;
  $('#space-nearby').replaceChildren();for(const s of nearby.slice(0,3)){const b=document.createElement('button');b.textContent=`${s.id} ${s.name} · 約 ${Math.round(s.distance)} 公尺`;b.onclick=()=>select(s.id,true);$('#space-nearby').append(b);}}
 $('#space-locate').onclick=()=>{if(!isAdmin())return;if(!navigator.geolocation){$('#space-gps').textContent='此瀏覽器不支援定位，可選站手動拍攝。';return;}stop();followed=false;$('#space-locate').disabled=true;$('#space-stop').disabled=false;$('#space-gps').textContent='定位中，請允許位置權限…';watch=navigator.geolocation.watchPosition(p=>{if(!isAdmin()){stop();return;}position={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,time:p.timestamp};update();},e=>{stop();$('#space-gps').textContent=e.code===1?'定位權限未開啟，可在瀏覽器設定允許；仍可依圖選站拍攝。':'定位暫時無法取得，可移到空曠處重試，或依圖選站拍攝。';},{enableHighAccuracy:true,maximumAge:5000,timeout:20000});};
 $('#space-stop').onclick=()=>{stop();$('#space-gps').textContent='已停止空間定位。';};$('#space-follow').onchange=()=>{followed=false;if($('#space-follow').checked){$('#space-confirm').checked=false;lock();update();}};
 $('#space-station').onchange=()=>select($('#space-station').value,true);$('#space-confirm').onchange=()=>{readRequest++;lock();if($('#space-confirm').checked&&$('#space-voice').checked)readStation(true);$('#space-status').textContent=$('#space-confirm').checked?fixedLocation?'本站位置已固定，四張照片會使用同一站點 GPS。':'本站已固定；目前沒有 20 秒內的可靠 GPS，照片將不附座標。可取消確認並重新定位後再拍。':'已取消本站確認，可重新選站或定位。';};$('#space-kind').onchange=instructions;$('#space-refresh').onclick=refresh;$('#space-next').onclick=()=>select(stations[(stations.findIndex(s=>s.id===$('#space-station').value)+1)%stations.length].id,true);
 async function capture(input){readRequest++;const file=input.files[0];if(!file||!isAdmin()||!$('#space-confirm').checked||busy)return;busy=true;const owner=getUser().uid,target=$('#space-station').value,kind=$('#space-kind').value,station=stations.find(s=>s.id===target),location=fixedLocation?{...fixedLocation}:undefined;$('#space-station').disabled=$('#space-kind').disabled=$('#space-next').disabled=$('#space-confirm').disabled=$('#space-follow').disabled=true;lock();$('#space-status').textContent='正在壓縮並保存照片…';try{const blob=await compress(file);if(!isAdmin()||getUser().uid!==owner)throw Error('登入已變更，請重新選擇照片');await store('put',{id:crypto.randomUUID(),owner,target,label:target,title:`${target} ${station.name} ${directions.find(([k])=>k===kind)[1]}`,description:'四向水平實景導覽照片；不含天空或地面補拍。',kind,location,blob,createdAt:Date.now(),state:'draft'});await renderDrafts();await refresh();$('#space-status').textContent='已保存本機。可接著拍下一個缺少的方向；拍完後到下方「本機待上傳照片」逐張確認上傳。';}catch(e){$('#space-status').textContent=`保存未完成：${e.message}。請保留相簿原圖。`;}finally{busy=false;input.value='';$('#space-station').disabled=$('#space-kind').disabled=$('#space-next').disabled=$('#space-confirm').disabled=$('#space-follow').disabled=false;lock();}}
 $('#space-camera').onchange=()=>capture($('#space-camera'));$('#space-album').onchange=()=>capture($('#space-album'));
 document.addEventListener('teacher-context-change',()=>{const next=getUser()?.uid||'';if(next===uid)return;uid=next;if(!isAdmin()){stop();position=undefined;$('#space-confirm').checked=false;lock();local=[];}else refresh();});document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();$('#space-gps').textContent='頁面進入背景，空間定位已停止；回來後請重新開始。';}});window.addEventListener('pagehide',stop);render();refresh();
 return {stop,refresh};
}
